def agent(observation, configuration):
    p=int(observation.get("player",0));step=min(int(observation.get("step",0)),len(ACTIONS[p])-1)
    action=copy.deepcopy(ACTIONS[p][step]);action["hands"]=action.get("hands",[])[:len(observation["farms"][p]["hands"])]
    return action
act=agent
